//             entity is missing - the old nodes then raise the same error as before.
const ha = global.get('homeassistant');
let states = null;
if (ha && typeof ha === 'object') {
    // keyed by the camel-cased server name; take a connected server that exposes its states
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    if (srv) states = srv.states;
}
const fallback = (why) => {
    const n = (context.get('fallbacks') || 0) + 1;
    context.set('fallbacks', n);
    node.status({ fill: 'yellow', shape: 'ring', text: `fallback to old reads (${why}) x${n}` });
    return [null, msg];
};
if (!states || Object.keys(states).length === 0) return fallback('no global HA states');

const missing = [];
const ent = (id) => {
    const e = states[id];
    if (!e) missing.push(id);
    return e;
};
// type conversions as the old outputProperties did them
const num = (id) => { const e = ent(id); return e ? Number(e.state) : undefined; };
const str = (id) => { const e = ent(id); return e ? String(e.state) : undefined; };
const raw = (id) => { const e = ent(id); return e ? e.state : undefined; };

// --- batteries (was: Your battery count, Loop start, 10 reads, Mapping, Loop step/until, Loop end)
const batteryCount = num('input_number.house_battery_count');
const batteries = [];
let i = 1;
do {   // the old loop ran the first battery before testing 'battery_index <= battery_count'
    const p = `marstek_m${i}_`;
    const b = {
        rs485_control_mode:          raw(`select.${p}rs485_control_mode`),
        battery_power:               num(`sensor.${p}battery_power`),
        max_charge_power:            num(`number.${p}max_charge_power`),
        max_discharge_power:         num(`number.${p}max_discharge_power`),
        battery_state_of_charge:     num(`sensor.${p}battery_state_of_charge`),
        discharging_cutoff_capacity: str(`input_number.${p}discharging_cutoff_capacity`),
        charging_cutoff_capacity:    str(`input_number.${p}charging_cutoff_capacity`),
        inverter_state:              raw(`sensor.${p}inverter_state`),
        battery_remaining_capacity:  num(`sensor.${p}battery_remaining_capacity`),
        battery_total_energy:        str(`sensor.${p}battery_total_energy`),
    };
    // 'Mapping', verbatim
    batteries.push({
        id: `M${i}`,
        power: parseInt(b.battery_power, 10),
        charging_max: parseInt(b.max_charge_power, 10),
        discharging_max: parseInt(b.max_discharge_power, 10),
        soc: parseInt(b.battery_state_of_charge, 10),
        soc_max: parseInt(b.charging_cutoff_capacity, 10),
        soc_min: parseInt(b.discharging_cutoff_capacity, 10),
        inverter: String(b.inverter_state),
        energy: Number(b.battery_remaining_capacity),
        energy_max: Number(b.battery_total_energy),
        rs485: String(b.rs485_control_mode)
    });
    i += 1;
} while (i <= batteryCount && i <= 20);   // 20 = guard against a runaway count

// --- settings (was: Prioritize battery M ... EV Stop Trigger Strategy)
const prioritize   = num('input_number.house_battery_control_prioritize_battery');
const cycle        = str('input_select.house_battery_control_priority_change_interval');
const hasImportE   = ent('input_boolean.house_battery_control_has_power_limit_import');
const hasExportE   = ent('input_boolean.house_battery_control_has_power_limit_export');
const importLimit  = num('input_number.house_battery_control_power_limit_import');
const exportLimit  = num('input_number.house_battery_control_power_limit_export');
const strategy     = str('input_select.house_battery_strategy');
const fullStop     = str('sensor.ev_is_charging');
const evStratE     = ent('input_select.house_battery_strategy_ev_stop_trigger_strategy');

if (missing.length) return fallback(`not in cache: ${missing[0]}${missing.length > 1 ? ' +' + (missing.length - 1) : ''}`);

msg.battery_count = batteryCount;
msg.batteries = batteries;
msg.prioritize_battery = prioritize;
msg.battery_priority_cycle_interval = cycle;
msg.grid_power_has_limit_import = hasImportE.state === 'on';
msg.grid_power_has_limit_export = hasExportE.state === 'on';
msg.grid_power_limit_import = importLimit;
msg.grid_power_limit_export = exportLimit;
flow.set('house_battery_strategy', strategy);
msg.full_stop_trigger = fullStop;
msg.ev_stop_trigger_strategy = String(evStratE.state);
// the last old node left these behind; keep them identical for anything downstream
msg.payload = String(evStratE.state);
msg.data = { ...evStratE };
msg._ha_fast_read = true;
// HBC+ v1.2 price guard: optional reads. A missing entity means no price guard (fail-open),
// never a fallback to the old reads - the price guard package may not be installed.
const opt = (id) => { const e = states[id]; return e ? String(e.state) : undefined; };
msg.price_guard = {
    mode: opt('input_select.house_battery_price_guard_mode'),
    state: opt('sensor.hbc_price_state'),
    source: opt('input_select.house_battery_strategy_dynamic_data_source'),
    phase_guard: opt('input_select.house_battery_phase_guard_mode'),
    phase_shared: opt('binary_sensor.hbc_phase_shared'),
};

node.status({ fill: 'green', shape: 'dot', text: `fast read: ${batteries.length} batteries @ ${new Date().toLocaleTimeString('nl-NL', { timeZone: 'Europe/Amsterdam' })}` });
return [msg, null];

// HBC+ heartbeat (max every 60 s) - HBC+ 2026-11-15: proves the control loop WORKS, not only
// that P1 updates arrive. It used to be fed from every P1 tick (before 'Read HA states (fast)'),
// so it stayed fresh while a strategy failed on every tick or every Modbus write failed, and the
// batteries kept their last command without anyone noticing.
//
// Now it is fed at the END of a cycle, through the link-in 'HBC+ cycle result':
//   - from 'Write latency': a write cycle finished. Good when at least one battery reported
//     without a write error (batteries_failed < batteries_done). One unreachable battery alone
//     does not stop the heartbeat (the Home Assistant fallback cannot reach it either); its
//     errors show up in hbc/health.
//   - from 'solutions present' (no solutions): the strategy returned without setpoints, e.g. a
//     deadband halt. Good when it returned without msg.error.
// A strategy that throws or times out, or a cycle in which every write fails, sends nothing.
// Publishes hbc/heartbeat (retained ISO time) at most once a minute -> sensor.hbc_last_run
// (packages/hbc_heartbeat.yaml). If it goes stale, HA hands the batteries back to their own
// firmware (forcible stop, anti-feed, RS485 off).
const EVERY_MS = 60 * 1000;
const now = Date.now();
const hhmm = (t) => new Date(t).toLocaleTimeString('nl-BE', { timeZone: 'Europe/Brussels', hour: '2-digit', minute: '2-digit' });

let good, why;
if (msg.batteries_done !== undefined) {
    const done = Number(msg.batteries_done) || 0;
    const failed = Number(msg.batteries_failed) || 0;
    good = done > 0 && failed < done;
    why = good ? `writes ok ${done - failed}/${done}` : `all ${done} battery writes failed`;
} else {
    good = !msg.error;
    why = good ? 'strategy ok, nothing to write' : `strategy error: ${(msg.error && msg.error.message) || 'unknown'}`;
}
if (!good) {
    node.status({ fill: 'red', shape: 'ring', text: `no heartbeat ${hhmm(now)}: ${why}`.slice(0, 100) });
    return null;
}
if (now - (flow.get('hbc_hb_last') || 0) < EVERY_MS) return null;
flow.set('hbc_hb_last', now);
node.status({ fill: 'green', shape: 'dot', text: `heartbeat ${hhmm(now)} (${why})` });
return { payload: { topic: 'hbc/heartbeat', payload: new Date(now).toISOString(), retain: true, qos: 1 } };

// HBC+ health (2026-11-15) - publishes hbc/health (retained JSON) -> sensor.hbc_health
// (packages/hbc_heartbeat.yaml). Checked every 30 s; sent when something changed, and every
// 5 minutes as a refresh (an unchanged payload adds nothing to the HA database).
//   status          ok | warning | error   (error = 3 or more errors in the last 10 minutes,
//                   warning = any warning, or 1-2 errors, in the last 10 minutes)
//   errors_10m, warnings_10m        counts in the last 10 minutes
//   errors_total, warnings_total    since the last deploy / Node-RED start
//   last_error(_at), last_warning(_at)   the latest message, as written to the Node-RED log
// The counts come from the HBC+ logger ('Custom logger' on this tab), which handles warnings
// and errors from every HBC+ flow, also when Insight mode is off.
const WINDOW_MS = 10 * 60 * 1000;
const REPUBLISH_MS = 5 * 60 * 1000;
const ERROR_LEVEL = 3;
const h = global.get('hbc_health') || {};
const now = Date.now();
const recent = (a) => (Array.isArray(a) ? a.filter(t => now - t <= WINDOW_MS).length : 0);
const iso = (t) => (Number(t) > 0 ? new Date(Number(t)).toISOString() : null);
const errors = recent(h.errors);
const warnings = recent(h.warnings);
const status = errors >= ERROR_LEVEL ? 'error' : (errors > 0 || warnings > 0) ? 'warning' : 'ok';
const payload = {
    status,
    errors_10m: errors,
    warnings_10m: warnings,
    errors_total: h.errors_total || 0,
    warnings_total: h.warnings_total || 0,
    last_error: h.last_error || '',
    last_error_at: iso(h.last_error_at),
    last_warning: h.last_warning || '',
    last_warning_at: iso(h.last_warning_at)
};
node.status({
    fill: status === 'ok' ? 'green' : status === 'warning' ? 'yellow' : 'red', shape: 'dot',
    text: `${status}: ${errors} errors, ${warnings} warnings in 10 min`
});
const key = JSON.stringify(payload);
const last = context.get('last') || {};
if (key === last.key && now - (last.t || 0) < REPUBLISH_MS) return null;
context.set('last', { key, t: now });
return { payload: { topic: 'hbc/health', payload: key, retain: true, qos: 1 } };

// HBC+ Phase planner (in loop) - v0.1, 2026-11-14
