// --- Price sensor (HBC+ v1.0) ------------------------------------------------------------
// input_text.house_battery_strategy_dynamic_price_sensor pins the price sensor for the
// macro. Without it, sources that name no sensor above (EasyEnergy/EnergyZero, ENTSO-E,
// GE-Spot, Tibber/Nordpool custom, Amber, Octopus, PVPC, Omie) rely on the macro's
// auto-detection, which can pick the wrong integration when two are installed.
// Sources that pass their own list (price_data: Zonneplan) ignore it.
const PRICE_SENSOR_ENTITY = 'input_text.house_battery_strategy_dynamic_price_sensor';
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object')
    : undefined;
const haStates = haSrv ? haSrv.states : undefined;
const pinned = haStates && haStates[PRICE_SENSOR_ENTITY] ? String(haStates[PRICE_SENSOR_ENTITY].state || '').trim() : '';

if (msg.dynamic.data_source !== 'None' && msg.dynamic.price_data === undefined && !msg.dynamic.gc_feed) {
    if (/^sensor\.[a-z0-9_]+$/.test(pinned)) {
        msg.dynamic.sensor = pinned;
        log(this, `Price sensor pinned: ${pinned}`);
    } else if (pinned && !['unknown', 'unavailable'].includes(pinned)) {
        log(this, `Ignoring ${PRICE_SENSOR_ENTITY} = '${pinned}': not a sensor entity id`, 'warn');
    }
    if (!msg.dynamic.sensor) {
        node.status({ fill: 'yellow', shape: 'ring', text: `${msg.dynamic.data_source}: sensor auto-detected` });
        log(this, `No price sensor named for ${msg.dynamic.data_source}; the macro auto-detects it. Set ${PRICE_SENSOR_ENTITY} to pin it.`);
    } else if (haStates && !haStates[msg.dynamic.sensor]) {
        node.status({ fill: 'red', shape: 'ring', text: `${msg.dynamic.sensor} not found` });
        log(this, `Price sensor ${msg.dynamic.sensor} does not exist in Home Assistant`, 'warn');
    } else {
        node.status({ fill: 'green', shape: 'dot', text: `${msg.dynamic.data_source}: ${msg.dynamic.sensor}` });
    }
} else {
    node.status({ fill: 'green', shape: 'dot', text: `${msg.dynamic.data_source}` });
}

log(this, "Performing API calls...");

// Output 1: the Cheapest Energy Hours macro. Output 2 (HBC+ v1.2): the Grid Clock feed.
return msg.dynamic.gc_feed ? [null, msg] : [msg, null];

// Init
msg.dynamic = {};
msg.log = [];
return msg;

// final template initialization
msg.dynamic.template_all = "";

// temporary template parts
let template_start = "";
let template_common = [];
let template_all = [];
let template_end = "";

// load the macro
// A data source may inject raw Jinja through msg.dynamic.template_prefix. That is used when
// the source data has to be reshaped before it can be handed to the macro — see the Zonneplan
// case in 'Data source settings'.
const template_lines = [`{% from 'cheapest_energy_hours.jinja' import cheapest_energy_hours %}`];
if (msg.dynamic.template_prefix) {
    template_lines.push(msg.dynamic.template_prefix);
}
template_lines.push(`{{ cheapest_energy_hours(`);
template_start = template_lines.join("\n") + "\n";
template_end = `) | to_json }}`;

// collect arguments | strings
const stringKeys = [
    'sensor',
    'attr_all',
    'value_key',
    'attr_today',
    'attr_tomorrow',
    'time_key',
    'source_settings'
];

stringKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}='${msg.dynamic[key]}'`);
    }
});

// collect arguments | boolean, integer
const otherKeys = [
    'datetime_in_data',
    'data_minutes',
    'price_data', // a Jinja variable name, so it must be emitted unquoted
];

otherKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}=${msg.dynamic[key]}`);
    }
});

// copy common items
template_all = [...template_common];

// collect all hours | via extra call
template_all.push(`hours="all"`);
template_all.push(`include_tomorrow=true`);
template_all.push(`mode="all"`);

/**
 * Formats an array of strings into a single string:
 * - Each item starts with 4 spaces.
 * - Each item ends with a comma, except the last one.
 * - Items are separated by a newline.
 */
function formatTemplateArray(array) {
    if (!array || array.length === 0) {
        return "";
    }

    const indent = "    "; 

    const formatted_lines = array.map((element, index) => {
        const suffix = (index < array.length - 1) ? "," : "";
        return `${indent}${element}${suffix}`;
    });

    return formatted_lines.join('\n');
}

// generate string templates
const template_all_string = formatTemplateArray(template_all);

// done
msg.dynamic.template_all = `${template_start}${template_all_string}${template_end}`;

return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// HBC+ v1.2 price guard: swap the strategy about to run while prices are below a threshold.
// msg.price_override is built once per tick in 'Strategy selection' (Home Battery Start).
// No override object = no change; Full stop is never changed. Monitor only records 'would'.
{
    const po = msg.price_override;
    const to = po && po.map && msg.target !== 'Full stop' ? po.map[msg.target] : undefined;
    if (to && to !== msg.target) {
        const step = `${msg.target} → ${to}`;
        if (po.active) { po.applied = step; msg.target = to; }
        else if (po.mode !== 'Off') { po.would = step; }
    }
}

// Logger
const log = (global.get('logger') || (() => {}));
log(this,`${msg.target} strategy`);

// Status
node.status({fill:"green",shape:"dot",text:`${msg.target}`});

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// Fetch error (HBC+ v1.0)
// Catches errors from the nodes in 'API call to Data Source' (for example the template
// render when HA is disconnected or the Cheapest Energy Hours macro fails). Without this
// node the message was lost, and a caller's link call waited for its 30 s timeout.
// Output 1: mark the fetch as failed and hand it to 'Cache data source', which keeps the
//           last valid prices (dynamic.stale) or replies with no_data.
// Output 2: an error inside 'Cache data source' itself goes straight back to the caller,
//           so a fault there can never loop.
const log = (global.get('logger') || (() => {}));
const err = msg.error || {};
const src = err.source || {};
if (log) log(this, `*FETCH ERROR* in '${src.name || src.type || '?'}': ${err.message || 'unknown error'}`, 'warn');
node.status({ fill: 'red', shape: 'ring', text: `error in ${src.name || src.type || '?'}` });

msg.dynamic = (msg.dynamic && typeof msg.dynamic === 'object') ? msg.dynamic : {};
msg.dynamic.no_data = true;
msg.dynamic.data_all = { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 };
msg.dynamic_from_cache = false;
delete msg.template;
delete msg.error;

if (src.name === 'Cache data source') return [null, msg]; // error in Cache data source
return [msg, null];

// logger, usage: log(this, "");
const log = (global.get('logger') || (() => {}));

// Cache data source (HBC+ v1.0)
// - A good price list is cached (flow.cached_dynamic_data) and passed on.
// - A failed fetch (no prices, macro error) no longer throws away prices that are still
//   valid: when the cache is from the same source and still covers the current interval,
//   that list is passed on with dynamic.stale = true and the cache is kept, so the next
//   run (Cache check) tries the source again. Only when nothing valid is left does the
//   failure go through as no_data; 'Determine dynamic strategy' then falls back to the
//   baseline strategy and HA raises binary_sensor.hbc_price_data_missing.
const dynamicData = msg.dynamic;

const isInvalid = (data) => {
    if (!data) return true;
    return JSON.stringify(data).toLowerCase().includes("error");
};
const coversNow = (c) => {
    const a = c && c.data_all;
    if (!a || !a.start || !a.hours || !Array.isArray(a.list) || a.list.length === 0) return false;
    const start = new Date(a.start).getTime();
    const end = start + a.hours * 3600000;
    const now = Date.now();
    return Number.isFinite(start) && now >= start && now < end;
};

if (isInvalid(dynamicData) || (dynamicData && dynamicData.no_data)) {
    const cached = flow.get("cached_dynamic_data");
    const source = dynamicData && dynamicData.data_source;
    if (cached && !cached.no_data && cached.data_source === source && coversNow(cached)) {
        log(this, `*FETCH FAILED* (${source}) - keeping the last valid prices until the source answers again`, "warn");
        node.status({ fill: "yellow", shape: "ring", text: `fetch failed, using last prices (${source})` });
        msg.dynamic = Object.assign({}, cached, { stale: true });
        return msg;
    }
    log(this, `*FETCH FAILED* (${source}) - no valid prices left, clearing cache`, "warn");
    node.status({ fill: "red", shape: "ring", text: `no prices (${source})` });
    flow.set("cached_dynamic_data", undefined);
} else {
    log(this, "Caching `msg.dynamic`");
    node.status({ fill: "green", shape: "dot", text: `cached (${dynamicData.data_source})` });
    const toCache = Object.assign({}, dynamicData);
    delete toCache.stale;
    flow.set("cached_dynamic_data", toCache);
}

return msg;

const handle = global.get('unhandledException');

if (typeof handle === 'function') handle(this);

return msg;

// Check if cache can be used or a new call to Data Source is required
const log = (global.get('logger') || (() => {}));

// Retrieve stored data from flow context
const cachedData = flow.get("cached_dynamic_data");

// The cache holds the fetched price list itself, so it is only valid for the data
// source it was fetched from. msg.dynamic.data_source is the CURRENT dropdown value
// (set by the 'Source' node just before); cachedData.data_source is the value at the
// time of caching. Without this check, switching the dropdown kept serving the old
// source's prices until the next scheduled cache clear (00:01 / 13:15 / 15:00),
// while the dashboard label already showed the new source.
const currentSource = msg.dynamic && msg.dynamic.data_source;
const sourceMatches = cachedData && cachedData.data_source === currentSource;

if (cachedData && !sourceMatches) {
    log(this, `*CACHE INVALID* cached source '${cachedData.data_source}' != selected '${currentSource}', refetching`);
    flow.set("cached_dynamic_data", undefined);
}

// After 13:00 the cache only counts if it already covers tomorrow.
// Day-ahead prices arrive somewhere after ~13:00; without this, a list fetched
// at 13:16 (before publication) was reused until the 15:01 or 00:01 cache clear,
// so the Timed/Dynamic view showed no prices for tomorrow while the source had them.
const coversTomorrow = (c) => {
    const a = c && c.data_all;
    if (!a || !a.start || !a.hours) return false;
    const end = new Date(new Date(a.start).getTime() + a.hours * 3_600_000);
    const midnight = new Date();
    midnight.setHours(24, 0, 0, 0);
    return end > midnight;
};
const awaitingTomorrow = new Date().getHours() >= 13 && !coversTomorrow(cachedData);

// Determine cache hit
if (cachedData && sourceMatches && !awaitingTomorrow) {
    // Cache HIT
    node.status({ fill: "green", shape: "dot", text: `Cache hit (${currentSource})` });
    log(this, `*CACHE HIT* using stored tariff data (${currentSource})`);

    // Attach cached data to the message so following nodes can use it
    msg.dynamic = cachedData;

    // Output #1
    return [msg, null];

} else {
    // Cache MISS (no cache, other source, or still waiting for tomorrow's prices)
    if (awaitingTomorrow && cachedData && sourceMatches) {
        log(this, "*CACHE STALE* no prices for tomorrow yet, refetching");
    }
    node.status({ fill: "yellow", shape: "ring", text: awaitingTomorrow && cachedData ? `Waiting for tomorrow (${currentSource})` : `Cache miss (${currentSource})` });

    // Output #2
    return [null, msg];
}

// Entry of the link-call section "Dynamic Fetch from Data Source" (HBC+ v1.0).
// Callers: Cache check in this tab, or ANY other flow via a link call (static to
// this link in, or dynamic by its name). Use a link-call timeout of >= 30 s.
//
// Request (all optional):
//   msg.dynamic.data_source  price source; default = input_select.house_battery_strategy_dynamic_data_source
//   msg.dynamic_use_cache    true = return this tab's cached prices when still valid (no fetch)
// Reply (always, via Return to caller):
//   msg.dynamic = { data_source, data_all: { list, list_marked, average, min, max, start, ... }, no_data? }
//   msg.dynamic_from_cache = true when the cache was used
// A successful fetch also refreshes this tab's cache (flow.cached_dynamic_data).
// A failed fetch (no prices, or an error in this section via 'Catch fetch errors') still
// replies: with the last valid prices (msg.dynamic.stale = true) or with msg.dynamic.no_data.
const log = (global.get('logger') || (() => {}));
const SRC_ENTITY = 'input_select.house_battery_strategy_dynamic_data_source';

const empty = (source, why) => {
    msg.dynamic = {
        data_source: source, no_data: true,
        data_all: { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 }
    };
    node.status({ fill: 'red', shape: 'ring', text: why });
    return [null, msg];
};

msg.dynamic = (msg.dynamic && typeof msg.dynamic === 'object') ? msg.dynamic : {};
let source = msg.dynamic.data_source;

if (!source) {
    // same lookup as 'Read HA states (fast)': HA states in global context
    const ha = global.get('homeassistant');
    const servers = (ha && typeof ha === 'object') ? Object.values(ha).filter(s => s && s.states && typeof s.states === 'object') : [];
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    source = srv && srv.states[SRC_ENTITY] ? srv.states[SRC_ENTITY].state : undefined;
    if (!source) {
        if (log) log(this, `No data source given and ${SRC_ENTITY} not readable (Expose to global context?)`, 'warn');
        return empty('unknown', 'no data source (HA states not available)');
    }
    msg.dynamic.data_source = source;
}

if (source === 'None') return empty('None', 'data source None');

if (msg.dynamic_use_cache === true) {
    const cached = flow.get('cached_dynamic_data');
    // same validity rule as Cache check: same source, and after 13:00 it must cover tomorrow
    const coversTomorrow = (c) => {
        const a = c && c.data_all;
        if (!a || !a.start || !a.hours) return false;
        const end = new Date(new Date(a.start).getTime() + a.hours * 3600000);
        const midnight = new Date();
        midnight.setHours(24, 0, 0, 0);
        return end > midnight;
    };
    if (cached && !cached.no_data && cached.data_source === source && (new Date().getHours() < 13 || coversTomorrow(cached))) {
        msg.dynamic = cached;
        msg.dynamic_from_cache = true;
        node.status({ fill: 'green', shape: 'dot', text: `cache (${source})` });
        return [null, msg];
    }
}

msg.dynamic_from_cache = false;
node.status({ fill: 'blue', shape: 'dot', text: `fetch (${source})` });
return [msg, null];

// Clear cache
flow.set("cached_dynamic_data", undefined);
return msg;

// logger, usage: log(this, "");
const log = (global.get('logger') || (() => {}));

// Conversion
const CONVERSION_RATE = parseFloat(RED.util.getMessageProperty(msg, "dynamic.value_conversion")) || 1;

// Check if the list exists and is an array to prevent errors
if (msg.dynamic && msg.dynamic.data_all && Array.isArray(msg.dynamic.data_all.list)) {

    // Create a new array where each value is multiplied
    if (Array.isArray(msg.dynamic.data_all?.list)) {
        msg.dynamic.data_all.list = msg.dynamic.data_all.list.map(v => v / CONVERSION_RATE * 100); // cents
    }

    // Update other fields
    if (msg.dynamic.data_all?.average) {
        msg.dynamic.data_all.average = parseInt(msg.dynamic.data_all.average / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.weighted_average){
        msg.dynamic.data_all.weighted_average = parseInt(msg.dynamic.data_all.weighted_average / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.min) {
        msg.dynamic.data_all.min = parseInt(msg.dynamic.data_all.min / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.max) {
        msg.dynamic.data_all.max = parseInt(msg.dynamic.data_all.max / CONVERSION_RATE * 100); // cents
    }
} else {
    // No usable price data from the selected source (integration missing, sensor empty,
    // macro error). Publish an EMPTY set instead of stopping: stopping left the previous
    // source's prices on sensor.hbc_energy_prices_data, so the chart kept showing them.
    // 'Cache data source' does not cache this, so the next run tries the source again.
    log(this, "*no price data* from the selected data source - publishing an empty set", "warn");
    msg.dynamic = msg.dynamic || {};
    msg.dynamic.no_data = true;
    msg.dynamic.data_all = { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 };
}

return msg;

// HBC+ v1.2: request for the public Grid Clock feed. No token, no registration: the
// request carries only the zone and the supplier's slug in the URL (see the user guide,
// 'Grid Clock feed', for what is sent). Base URL: tab env var GRIDCLOCK_FEED_URL, else
// production. If-None-Match with the last ETag, so an unchanged file costs a 304.
const log = (global.get('logger') || (() => {}));
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object') : undefined;
const state = (id) => {
    const e = haSrv && haSrv.states[id];
    const v = e ? String(e.state || '').trim() : '';
    return ['', 'unknown', 'unavailable'].includes(v) ? '' : v;
};

const BASE = String(env.get('GRIDCLOCK_FEED_URL') || 'https://cdn.gridclock.eu/v1/hbc').replace(/\/+$/, '');
const zone = state('input_select.house_battery_gridclock_zone') || 'NL';
let slug = state('input_text.house_battery_gridclock_provider_slug');
if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug)) slug = 'market';
const url = `${BASE}/${encodeURIComponent(zone)}/${slug}/latest.json`;

const cache = flow.get('gc_feed_cache') || {};
msg.url = url;
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
if (cache.url === url && cache.etag) msg.headers['If-None-Match'] = cache.etag;
msg.requestTimeout = 20000;
msg.gc = { zone, slug, url, operator: state('input_text.house_battery_gridclock_grid_operator_name') };
delete msg.payload;
node.status({ fill: 'blue', shape: 'dot', text: `${zone}/${slug}` });
log(this, `Grid Clock feed: ${zone}/${slug}`);
return msg;

// HBC+ v1.2: Grid Clock feed -> msg.dynamic.data_all in the same shape as the macro path
// after 'Convert price' (ct/kWh), plus data_all.sell. Output 1 -> Cleanup -> Price split ->
// Cache data source (a failed fetch keeps the last valid prices there). Output 2 -> the
// HA event hbc_gridclock_status (sensor.hbc_grid_clock_feed).
// BE: the chosen grid operator's ct/kWh (incl. VAT) is added to the buy price, and to the
// sell price only where sell = buy (net metering), from the supplier index ('gc_index').
const log = (global.get('logger') || (() => {}));
const g = msg.gc || {};
const cache = flow.get('gc_feed_cache') || {};
const nowIso = new Date().toISOString();

const fail = (why) => {
    node.status({ fill: 'red', shape: 'ring', text: why });
    log(this, `Grid Clock feed ${g.zone}/${g.slug}: ${why}`, 'warn');
    msg.dynamic = msg.dynamic || {};
    msg.dynamic.no_data = true;
    msg.dynamic.data_all = { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 };
    const status = { payload: { state: 'error', reason: why, zone: g.zone, slug: g.slug, checked_at: nowIso } };
    delete msg.payload;
    return [msg, status];
};

let doc = null, how = '';
if (msg.statusCode === 304 && cache.url === g.url && cache.doc) {
    doc = cache.doc; how = 'not modified';
} else if (msg.statusCode === 200 && msg.payload && typeof msg.payload === 'object'
           && Array.isArray(msg.payload.slots)) {
    doc = msg.payload; how = 'ok';
    const h = msg.headers || {};
    flow.set('gc_feed_cache', { url: g.url, etag: h.etag || h.ETag || null, doc });
} else {
    return fail(msg.statusCode ? `HTTP ${msg.statusCode}` : 'no answer from cdn.gridclock.eu');
}

const minutes = Number(doc.resolution_minutes) || 15;
const step = minutes * 60000;
// Contiguous run from the first slot; a gap ends the list (same rule as the publisher).
const slots = [];
for (const s of doc.slots) {
    const t = Date.parse(s && s.start);
    const buy = Number(s && s.buy);
    if (!Number.isFinite(t) || !Number.isFinite(buy)) break;
    if (slots.length && t !== slots[slots.length - 1].t + step) break;
    const sell = (s.sell === null || s.sell === undefined || !Number.isFinite(Number(s.sell))) ? null : Number(s.sell);
    slots.push({ t, buy, sell });
}
if (!slots.length) return fail('feed has no slots');

const idx = (flow.get('gc_index') || {})[g.zone];
let grid = 0;
if (g.operator && idx && Array.isArray(idx.grid_operators)) {
    const op = idx.grid_operators.find(o => o.grid_operator === g.operator);
    grid = Number(op && op.ct_per_kwh) || 0;
}
const r = (v) => Math.round(v * 10000) / 10000;
const list = [], sell = [];
for (const s of slots) {
    const net = s.sell === null || Math.abs(s.sell - s.buy) < 1e-9;
    list.push(r(s.buy + grid));
    sell.push(r(s.sell === null ? s.buy + grid : s.sell + (net ? grid : 0)));
}
const avg = list.reduce((a, b) => a + b, 0) / list.length;
msg.dynamic.data_all = {
    list, sell,
    start: new Date(slots[0].t).toISOString(),
    hours: slots.length * minutes / 60,
    datapoints: slots.length,
    datapoints_per_hour: 60 / minutes,
    average: Math.round(avg),
    min: Math.min(...list), max: Math.max(...list),
};
msg.dynamic.gc = { zone: g.zone, slug: doc.slug, provider: doc.provider, product: doc.product,
                   net_metering_ends_on: doc.net_metering_ends_on || null, grid_ct_kwh: grid };
delete msg.payload;

const until = new Date(slots[slots.length - 1].t + step).toISOString();
const label = doc.provider ? [doc.provider, doc.product].filter(Boolean).join(' – ') : 'Market price (no supplier)';
node.status({ fill: 'green', shape: 'dot', text: `${how}: ${label}, ${slots.length} slots` });
const status = { payload: {
    state: how, reason: '', zone: g.zone, slug: doc.slug, supplier: label,
    grid_operator: g.operator || null, grid_ct_kwh: grid,
    net_metering_ends_on: doc.net_metering_ends_on || null,
    slots: slots.length, prices_until: until, checked_at: nowIso } };
return [msg, status];

// HBC+ v1.2: every source carries a sell list next to the buy list (data_all.list).
// The Grid Clock feed brings its own; for every other source sell = buy, which is exactly
// how v1.1 valued a kWh (net metering). Runs inside the fetch section, so the cache and
// every link-call caller get the same lists.
const a = msg.dynamic && msg.dynamic.data_all;
if (a && Array.isArray(a.list)) {
    if (!Array.isArray(a.sell) || a.sell.length !== a.list.length) a.sell = a.list.slice();
    const split = a.sell.some((v, i) => v !== a.list[i]);
    node.status({ fill: split ? 'green' : 'grey', shape: 'dot', text: split ? 'buy + sell' : 'sell = buy' });
}
return msg;

// HBC+ v1.2: fetch v1/hbc/{zone}/index.json (suppliers and grid operators of the zone).
// Triggered at start, daily at 00:10 and when the zone changes (then prices refresh too).
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object') : undefined;
const state = (id) => {
    const e = haSrv && haSrv.states[id];
    const v = e ? String(e.state || '').trim() : '';
    return ['', 'unknown', 'unavailable'].includes(v) ? '' : v;
};

const BASE = String(env.get('GRIDCLOCK_FEED_URL') || 'https://cdn.gridclock.eu/v1/hbc').replace(/\/+$/, '');
// Never guess the zone: right after a (re)start HA's states may not be loaded yet, and a
// default zone would replace the supplier list and drop the remembered supplier. Wait and
// retry (every 10 s, up to 5 min, via output 2); the HA (re)start trigger below also lands here.
const zone = state('input_select.house_battery_gridclock_zone');
if (!zone) {
    const tries = (msg.gc_tries || 0) + 1;
    if (tries > 30) {
        node.status({ fill: 'red', shape: 'ring', text: 'HA states not available' });
        return null;
    }
    node.status({ fill: 'yellow', shape: 'ring', text: `waiting for HA (${tries})` });
    msg.gc_tries = tries;
    setTimeout(() => node.send([null, msg]), 10000);   // output 2 loops back to this node
    return null;
}
delete msg.gc_tries;
node.status({});
msg.gc_zone = zone;
msg.gc_refresh = msg.topic === 'input_select.house_battery_gridclock_zone';
msg.url = `${BASE}/${encodeURIComponent(zone)}/index.json`;
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.requestTimeout = 20000;
delete msg.payload;
return msg;

// HBC+ v1.2: index.json -> the options of the supplier and grid-operator selects.
// The select only shows names; the choice is kept as a slug in an input_text, because HA
// forgets runtime options after a restart. Labels map back to slugs via flow 'gc_labels'.
const log = (global.get('logger') || (() => {}));
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object') : undefined;
const state = (id) => {
    const e = haSrv && haSrv.states[id];
    const v = e ? String(e.state || '').trim() : '';
    return ['', 'unknown', 'unavailable'].includes(v) ? '' : v;
};

const MARKET = 'Market price (no supplier)';
const NONE_OP = 'None';
const zone = msg.gc_zone;
if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== 'object' || !Array.isArray(msg.payload.providers)) {
    node.status({ fill: 'red', shape: 'ring', text: `${zone}: index ${msg.statusCode || 'no answer'}` });
    log(this, `Grid Clock index ${zone}: ${msg.statusCode || 'no answer'}`, 'warn');
    return null;
}
// The zone changed while this index was on its way: a newer request follows, skip this one
// (it would otherwise reset the remembered supplier).
const zoneNow = state('input_select.house_battery_gridclock_zone');
if (zoneNow && zoneNow !== zone) return null;
const doc = msg.payload;
const all = flow.get('gc_index') || {};
all[zone] = doc;
flow.set('gc_index', all);

const labels = {};
labels[MARKET] = '';
for (const p of doc.providers) {
    let label = [p.provider, p.product].filter(Boolean).join(' – ');
    if (!p.has_sell) label += ' (no sell price)';
    labels[label] = p.slug;
}
flow.set('gc_labels', labels);
const options = Object.keys(labels);
const slug = state('input_text.house_battery_gridclock_provider_slug');
const chosen = options.find(l => labels[l] === slug) || MARKET;
const operators = [NONE_OP, ...(doc.grid_operators || []).map(o => o.grid_operator)];
const opName = state('input_text.house_battery_gridclock_grid_operator_name');
const op = operators.includes(opName) ? opName : NONE_OP;

const sel = 'input_select.house_battery_gridclock_provider';
const opSel = 'input_select.house_battery_gridclock_grid_operator';
msg.gc_calls = [
    { action: 'input_select.set_options', target: { entity_id: sel }, data: { options } },
    { action: 'input_select.select_option', target: { entity_id: sel }, data: { option: chosen } },
    { action: 'input_select.set_options', target: { entity_id: opSel }, data: { options: operators } },
    { action: 'input_select.select_option', target: { entity_id: opSel }, data: { option: op } },
];
// The supplier vanished from the index (or none chosen yet): fall back to the market price.
if (slug && labels[chosen] !== slug) {
    msg.gc_calls.push({ action: 'input_text.set_value', target: { entity_id: 'input_text.house_battery_gridclock_provider_slug' }, data: { value: '' } });
    msg.gc_refresh = true;
}
// The grid operator is not in this zone's list (zone changed, or gone from the index): forget it.
// The select change to 'None' cannot do this, 'Choice -> slug' ignores a single-option select.
if (opName && op !== opName) {
    msg.gc_calls.push({ action: 'input_text.set_value', target: { entity_id: 'input_text.house_battery_gridclock_grid_operator_name' }, data: { value: '' } });
    msg.gc_refresh = true;
}
node.status({ fill: 'green', shape: 'dot', text: `${zone}: ${doc.providers.length} suppliers` });
delete msg.payload;
return msg;

// HBC+ v1.2: a supplier or grid operator was picked on the dashboard. Store it (slug or
// operator name) in its input_text and refresh the prices. Our own select_option calls
// land here too; they change nothing, so they stop here.
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object') : undefined;
const state = (id) => {
    const e = haSrv && haSrv.states[id];
    const v = e ? String(e.state || '').trim() : '';
    return ['', 'unknown', 'unavailable'].includes(v) ? '' : v;
};

const MARKET = 'Market price (no supplier)';
const NONE_OP = 'None';
// After a restart of Home Assistant the selects come back with only their YAML option
// ('Market price (no supplier)' / 'None') until 'Index apply' rebuilds them. That reset is
// not a choice: ignore it, or the remembered supplier and grid operator would be wiped.
const sel = (msg.data && msg.data.new_state) || (haSrv && haSrv.states[msg.topic]);
const opts = (sel && sel.attributes && sel.attributes.options) || [];
if ((msg.payload === MARKET || msg.payload === NONE_OP) && opts.length <= 1) return null;
let entity, value;
if (msg.topic === 'input_select.house_battery_gridclock_provider') {
    const labels = flow.get('gc_labels');
    if (!labels || !(msg.payload in labels)) return null;   // index not loaded yet
    entity = 'input_text.house_battery_gridclock_provider_slug';
    value = labels[msg.payload];
} else {
    entity = 'input_text.house_battery_gridclock_grid_operator_name';
    value = msg.payload === NONE_OP ? '' : String(msg.payload || '');
}
if (state(entity) === value) return null;
msg.gc_calls = [{ action: 'input_text.set_value', target: { entity_id: entity }, data: { value } }];
msg.gc_refresh = true;
return msg;

// Runs the queued HA calls one by one (set_options must land before select_option).
// Output 1 -> HA call -> back here. Output 2 when the queue is empty and prices must refresh.
const q = Array.isArray(msg.gc_calls) ? msg.gc_calls : [];
if (!q.length) return [null, msg.gc_refresh ? msg : null];
msg.payload = q.shift();
msg.gc_calls = q;
return [msg, null];

const log = (global.get('logger') || (() => {}));
const e = msg.error || {};
log(this, `Grid Clock suppliers: ${e.message || 'error'} in '${(e.source && e.source.name) || '?'}'`, 'warn');
node.status({ fill: 'red', shape: 'ring', text: e.message || 'error' });
return null;

// HBC+ v1.2: HA (re)started or Node-RED (re)connected. HA loads the supplier and grid-operator
// selects with only their YAML options ("Market price (no supplier)" / "None"), so the
// dashboard would show those although the remembered choice (input_texts) is still in force.
// Fetch the index again: that restores the options and shows the remembered choice.
// Client events come in bursts (states_loaded, services_loaded, running, ...): once per 30 s.
const what = typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload || msg.event_type || '');
if (!/running|ready/i.test(what)) return null;
const now = Date.now();
if (now - (context.get('last') || 0) < 30000) return null;
context.set('last', now);
return { topic: 'ha_restart' };

// Logger
const log = (global.get('logger') || (() => {}));
log(this,`full stop`);

// Process
let solution_array = [];

// Add a solution per battery
msg.batteries.forEach(battery => {
    solution_array.push({ id: battery.id, 
    mode: "stop", // disengages Marstek Battery
    power: 0 }); // set power to 0W
});

// OUTPUT
msg.solutions = solution_array;
return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if (handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// Helios placeholder (HBC+ v1.0)
// HBC+ keeps 'Helios' in the strategy list for a future HELIOS integration, but the HELIOS
// flow itself is not part of HBC+. Without this tab, selecting 'Helios' would make
// Home Battery Start fail on a link call with no target, and the batteries would keep their
// last setpoint. This placeholder runs Full stop instead and warns (at most every 10 min).
// Delete this tab before you import a real HELIOS flow: two 'Helios' link-in nodes make
// the dynamic link call ambiguous.
const log = (global.get('logger') || (() => {}));
const now = Date.now();
if (now - (context.get('lastWarn') || 0) > 600000) {
    context.set('lastWarn', now);
    if (log) log(this, "**Helios** selected, but the HELIOS flow is not installed - running Full stop", "warn");
}
node.status({ fill: 'yellow', shape: 'ring', text: `HELIOS not installed: Full stop (${new Date().toLocaleTimeString()})` });
msg.target = "Full stop";
RED.util.setMessageProperty(msg, "strategy.display", "Helios (not installed)", true);
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if (handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// explain
const log = (global.get('logger') || (() => {}));
log(this,"Using `Self-consumption` to charge with surplus PV")

// use the self consumption strategy to charge when there is PV surplus
msg.target = "Self-consumption";

// tell that strategy to disallow discharging
const DISCHARGE_DISABLED = true;
RED.util.setMessageProperty(msg,"advanced_settings.discharge_disabled",DISCHARGE_DISABLED,true);

return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

/* Mode selection 
 * 
 * Peak shaving can be triggered by:
 * - Grid power exceeds the import/export limit set by the user
 * 
 * Peak shaving will persist while:
 * - Grid power exceeds the import/export limit set by the user
 * - Batteries are applied to keep system below the limit set by the user
 * 
 * The first is checked in this node.
 * The latter is checked in the last function node of the Peak Shaving flow.
 * Both set the last_power_limit_violation flow variable to Date.now() to persist peak shaving.
 * 
 * PEAK_SHAVING_TIMEOUT_SEC is advised to be kept above atleast 3-5 seconds, to account for rate limiters and other power saving options.
*/

// Timestamp
const now = Date.now();

// Logger
const log = (global.get('logger') || (() => {}));

// Configuration & State recovery
const PEAK_SHAVING_TIMEOUT_SEC = 10;
let isPeakShaving = flow.get("is_peak_shaving") ?? false;
let lastPowerLimitViolation = flow.get("last_power_limit_violation") ?? now;
let isPowerLimitViolation = false;
let peakDirection = flow.get("peak_shave_direction") || null;
let powerLimit = Number(flow.get("peak_shave_power_limit")) || 0;

// Input data | grid
const P1_power = parseInt(RED.util.getMessageProperty(msg, "grid_power") || 0);
// Input data | Charge PV
const hasImportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_import") || false;
const importLimit = parseInt(RED.util.getMessageProperty(msg, "grid_power_limit_import") || 0);
// Input data | Sell PV
const hasExportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_export") || false;
const exportLimit = parseInt(RED.util.getMessageProperty(msg, "grid_power_limit_export") || 0);

// ACTIVATE shaving
// Latch the direction and limit at the moment of the real violation. During the
// release timeout the battery response can flip P1 import/export, but that
// should not turn an import shave into an export shave or vice versa.
if (hasImportLimit && (P1_power > importLimit)) {
    isPeakShaving = true;
    isPowerLimitViolation = true;
    peakDirection = "import";
    powerLimit = importLimit;
}
if (hasExportLimit && (P1_power < exportLimit)) {
    isPeakShaving = true;
    isPowerLimitViolation = true;
    peakDirection = "export";
    powerLimit = exportLimit;
}

// UPDATE timer or continue
if (isPowerLimitViolation) lastPowerLimitViolation = now;

// CALCULATE release logic
// Seconds since the last time the power limit was exceeded
let secondsSinceLastViolation = Math.floor((now - lastPowerLimitViolation) / 1000);

// RELEASE shaving logic
// Only release if we are currently shaving AND the timeout has passed
if (isPeakShaving && (secondsSinceLastViolation >= PEAK_SHAVING_TIMEOUT_SEC)) {
    isPeakShaving = false;
    peakDirection = null;
    powerLimit = 0;
    log(this,"Peak Shaving released, resume normal operation");
}

// UI & OUTPUT Logic
if (isPeakShaving) {
    // Timeout progress
    const secondsRemaining = PEAK_SHAVING_TIMEOUT_SEC - secondsSinceLastViolation;
    // Set latched grid power limit
    msg.payload = powerLimit;
    // UI
    node.status({
        fill: "yellow",
        shape: "dot",
        text: isPowerLimitViolation ? "Peak Shaving" : "Peak Shaving: release in " + secondsRemaining + "s"
    });
} else {
    // UI
    node.status({
        fill: "green",
        shape: "dot",
        text: "Grid OK - " + msg.target
    });
}

// Persist state for next run
flow.set("is_peak_shaving", isPeakShaving); 
flow.set("peak_shave_direction", peakDirection);
flow.set("peak_shave_power_limit", powerLimit);
if (isPowerLimitViolation) flow.set("last_power_limit_violation", now); // Power limit exceeded. Update the lastPowerLimitViolation timestamp to current time

// Finalize msg
RED.util.setMessageProperty(msg, "strategy.is_peak_shaving", isPeakShaving, true);
RED.util.setMessageProperty(msg, "strategy.peak_direction", peakDirection, true);

// OUTPUT
return msg;

// Logger
const log = (global.get('logger') || (() => {}));

// Explain
log(this,`**Peak shaving mode** postponing '${msg.target}' strategy`);
node.status({ fill: "green", shape: "dot", text: `postponing '${msg.target}' strategy`});

// Original target
const ORIGINAL_TARGET = msg.target;

// Use the PID controller strategy
msg.target = "Self-consumption";
// Set the grid power limit
msg.house_target_grid_consumption_in_w = msg.payload;

// Type of peak shave
const peakDirection = RED.util.getMessageProperty(msg, "strategy.peak_direction");
const DISABLED = true;

switch (peakDirection) {
    case "import":
        // Ask PID to help shave import peak
        RED.util.setMessageProperty(msg, "advanced_settings.charge_disabled", DISABLED, true);    
        break;
    case "export":
        // Ask PID to help shave export peak
        RED.util.setMessageProperty(msg, "advanced_settings.discharge_disabled", DISABLED, true);
        break;
    default:
        log(this, `Unknow peak type ${peakDirection}, peak shave failed`, "warn");       
        node.status({ fill: "red", shape: "dot", text: `peak type ${peakDirection}, peak shave failed`});
        // Set a safe value
        msg.house_target_grid_consumption_in_w = 0;
}

return msg;

// Logger
const log = (global.get('logger') || (() => {}));

// INPUT
const PID_assigned = msg.pid?.load_assigned ?? 0; // calculated battery power delivery, see footnote_1 why this is 0 by default
const isCharging = msg.batteries_charging || false;

// HOLD peak shave when:
if(PID_assigned > 0 && !isCharging) {
    // The batteries are still required to reduce the power peak
    log(this,`**Peak shaving continues**, batteries still required for peak reduction`);
    // Reset timeout timer
    flow.set("last_power_limit_violation", Date.now()); 
    // UI
    node.status({fill:"yellow",shape:"dot",text:`Holding peak shave, batteries still required for ${PID_assigned} W`});
} else {
    // No solution or batteries not required - let timer run out
    node.status({fill:"green",shape:"dot",text:`Relax`});
}

return msg;

// FOOTNOTE_1: 
// Self-consumption won't return `msg.solutions` nor `msg.pid.load_assigned` when:
// - P1 is near or at it's target grid consumption (aka inside deadband)
// - when a non-blocking error occurs
// 
