const cfg = msg.timed_cfg;
const ok = cfg && typeof cfg === 'object' && Array.isArray(cfg.periods) && cfg.periods.length === 5
    && Number.isFinite(Number(cfg.utc_offset_s));
if (!ok) {
    node.status({ fill: 'red', shape: 'ring', text: `settings render failed ${new Date().toLocaleTimeString()}` });
    node.warn('[Timed] settings template returned nothing usable - keeping the previous snapshot');
    return null;
}
cfg.stamp = Date.now();
flow.set('timed_cfg', cfg);
const on = cfg.periods.filter(x => x.enabled).map(x => x.id).join('');
node.status({ fill: 'grey', shape: 'dot', text: `periods ${on || '-'} @ ${new Date().toLocaleTimeString()}` });
return null;                         // a settings refresh never continues into the flow

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_a1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_a2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_b1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_b2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_c1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_c2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_d1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_d2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

msg.__config = {
    startTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_e1'),
    endTime: RED.util.getMessageProperty(msg,'house_battery_strategy_timed_period_e2'),
    startOffset: 0,
    endOffset: 0
}

return msg;

// Detect charge <-> discharge oscillation per battery
const T         = Number(env.get('THRESHOLD_W')) || 1200;
const WINDOW_MS = (Number(env.get('WINDOW_S')) || 180) * 1000;
const MIN_FLIPS = Number(env.get('MIN_FLIPS')) || 5;

const p = Number(msg.payload);
if (!Number.isFinite(p)) return null;
const now = Date.now();

// Update tracking (always, so status stays live)
const tracks = flow.get('osc_tracks') || {};
const t = tracks[msg.topic] || { zone: null, flips: [] };

// Hysteresis: only change zone when clearly past +T or -T
let zone = t.zone;
if (p > T) zone = 'charge';
else if (p < -T) zone = 'discharge';

if (t.zone && zone !== t.zone) t.flips.push(now);
t.zone = zone;
t.flips = t.flips.filter(ts => now - ts <= WINDOW_MS);
tracks[msg.topic] = t;
flow.set('osc_tracks', tracks);

const name = msg.topic.replace('sensor.', '');
const guardActive = flow.get('guard_active') === true;
const inGrace = now < (flow.get('grace_until') || 0);

node.status({
    fill: guardActive ? 'red' : (inGrace ? 'blue' : (t.flips.length ? 'yellow' : 'green')),
    shape: 'dot',
    text: `${name}: ${Math.round(p)}W | ${t.flips.length}/${MIN_FLIPS} flips` +
          (guardActive ? ' | GUARD ACTIVE' : (inGrace ? ' | grace' : ''))
});

if (guardActive || inGrace) return null;

if (t.flips.length >= MIN_FLIPS) {
    const flips = t.flips.length;
    flow.set('osc_tracks', {}); // reset all windows
    return {
        topic: 'oscillation',
        osc: { entity: msg.topic, flips: flips, window_s: WINDOW_MS / 1000, power: Math.round(p), threshold: T }
    };
}
return null;

// Switch to Full stop and remember the previous strategy
const cur = msg.strategy;
const osc = msg.osc || { entity: 'unknown', flips: 0, window_s: 0 };
const STOP_S = Number(env.get('STOP_S')) || 120;
const dry = String(env.get('DRY_RUN')).toLowerCase() === 'true';

if (flow.get('guard_active') === true) return null;

if (!cur || cur === 'unknown' || cur === 'unavailable') {
    node.status({ fill: 'grey', shape: 'ring', text: `skipped: strategy '${cur}'` });
    return null;
}
if (cur === 'Full stop') {
    node.status({ fill: 'grey', shape: 'ring', text: 'skipped: already Full stop' });
    return null;
}

const what = `Oscillation on ${osc.entity} (${osc.flips} charge/discharge flips in ${osc.window_s}s)`;

if (dry) {
    msg.message = `[DRY RUN] ${what}. Would switch '${cur}' -> 'Full stop' for ${STOP_S}s`;
    node.warn(msg.message);
    node.status({ fill: 'yellow', shape: 'ring', text: `dry run @ ${new Date().toLocaleTimeString()}` });
    return [null, msg];
}

flow.set('guard_active', true);
flow.set('prev_strategy', cur);
flow.set('trigger_count', (flow.get('trigger_count') || 0) + 1);

msg.prev_strategy = cur;
msg.delay = STOP_S * 1000;
const ts = new Date().toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });
msg.message = `${what}. Strategy '${cur}' -> 'Full stop' for ${STOP_S}s`;
msg.notify = {
    title: '⚠️ Battery oscillation – Full stop',
    message: `${ts}\nFull stop activated for ${STOP_S}s.\n${what}.\nPrevious strategy: ${cur}`
};
node.status({ fill: 'red', shape: 'dot', text: `Full stop since ${ts} (was: ${cur})` });
return [msg, msg, msg];

// Ask the strategy arbiter for 'Full stop' (highest priority).
msg.arbiter = { requester: 'guard', action: 'hold', strategy: 'Full stop', reason: msg.message || 'battery oscillation' };
msg.target = 'Strategy request';   // link call (dynamic) finds the link-in by name
return msg;

// Restore previous strategy after the Full stop pause
const GRACE_S = Number(env.get('GRACE_S')) || 60;
const prev = flow.get('prev_strategy');
const cur = msg.strategy;

flow.set('guard_active', false);
flow.set('prev_strategy', null);
flow.set('osc_tracks', {});
flow.set('grace_until', Date.now() + GRACE_S * 1000);

if (!prev) {
    // Nothing remembered in memory (e.g. Node-RED restarted during the pause): still release,
    // the arbiter keeps its state in HA and restores the right strategy.
    node.status({ fill: 'grey', shape: 'ring', text: 'release sent (no local state)' });
    return [msg, null, null];
}
const ts = new Date().toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });

if (cur !== 'Full stop') {
    msg.message = `Strategy was changed to '${cur}' during the pause - not restoring '${prev}'`;
    msg.notify = {
        title: 'ℹ️ Battery oscillation – pause ended',
        message: `${ts}\nPause ended. Strategy was changed manually to '${cur}' – '${prev}' not restored.`
    };
    node.status({ fill: 'grey', shape: 'ring', text: `not restored (now: ${cur})` });
    return [msg, msg, msg];   // release anyway; the arbiter keeps the manual choice
}

msg.prev_strategy = prev;
msg.message = `Oscillation pause finished - strategy restored to '${prev}'`;
msg.notify = {
    title: '✅ Battery oscillation – strategy restored',
    message: `${ts}\nFull stop ended. Strategy restored to '${prev}'.`
};
node.status({ fill: 'green', shape: 'dot', text: `restored '${prev}' @ ${ts}` });
return [msg, msg, msg];

// End of the pause: release the hold. The arbiter restores the strategy that was
// active before, or keeps a manual change made during the pause.
msg.arbiter = { requester: 'guard', action: 'release', reason: 'oscillation pause ended' };
msg.target = 'Strategy request';   // link call (dynamic) finds the link-in by name
return msg;

// HBC+ (2026-11-15): a Catch node keeps the errors it catches out of the Node-RED log.
// Hand them to the HBC+ logger: Node-RED log (max once a minute per message) and hbc/health.
const handle = global.get('unhandledException');
if (typeof handle === 'function') handle(this);
else node.error(`${(msg.error && msg.error.message) || 'unknown error'}`);
return msg;

// HBC+ Phase planner - MONITOR ONLY (HBC+ v1.0, 2026-11-14)
// Read-only: reads Home Assistant states from global context (server option 'Expose to global
// context', already on for HBC) and publishes what HBC+ WOULD do per phase. It writes nothing to
// the batteries and is not wired into the HBC control loop, so HBC behaves exactly as before.
//
// Per phase (L1..L3) it publishes hbc/phase/Lx (retained JSON) -> sensor.hbc_phase_lx_active:
//   active / standby  battery HBC+ would let work / keep waiting (sharing: 'M1+M4')
//   mode              direction on that phase now: charge | discharge | idle
//   room              fuse room for that direction (W), charge_room / discharge_room both
//   setpoint          power HBC+ would give the active battery(ies) now (W)
//   hbc_power         what the batteries on that phase actually do now (W, + = charging)
//   would             plain-language difference between HBC now and HBC+ ('ok' if none)
//   reason, since     why this battery, since when (ISO)
// and hbc/phase/summary -> sensor.hbc_phase_findings (number of phases where HBC+ would act).
//
// Signs: sensor.marstek_mN_battery_power > 0 = charging; sensor.p1_meter_power_phase_N > 0 = import.

const PHASES = ['L1', 'L2', 'L3'];
const DEADBAND_W = 50;        // phase battery power below this = idle
const RUNNING_W = 100;        // a battery above this counts as running
const SHARE_START_W = 300;    // shared headroom: partner starts with at least this much room left
const SHARE_STOP_W = 100;     // ... and stops below this
const PUBLISH_EVERY_MS = 30000; // republish unchanged state at most this often
const ROUND_W = 50;           // rooms/setpoints rounded for publishing (fewer HA state changes)

// ---- HA states from global context ----
const ha = global.get('homeassistant');
let states = null;
if (ha && typeof ha === 'object') {
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    if (srv) states = srv.states;
}
if (!states) { node.status({ fill: 'red', shape: 'ring', text: 'no HA states in global context' }); return null; }
const raw = (id) => (states[id] ? states[id].state : undefined);
const usable = (v) => v !== undefined && v !== null && v !== '' && v !== 'unknown' && v !== 'unavailable';
const num = (id, def) => { const v = raw(id); const n = Number(v); return usable(v) && Number.isFinite(n) ? n : def; };
const str = (id, def) => { const v = raw(id); return usable(v) ? String(v) : def; };

// ---- settings ----
const cfg = {
    mode: str('input_select.house_battery_phase_guard_mode', 'Off'),
    sharing: str('input_select.house_battery_phase_sharing', 'One battery per phase') === 'Shared headroom',
    selection: str('input_select.house_battery_phase_selection', 'SoC balance'),
    limit: num('input_number.house_battery_phase_limit_w', 3680),
    circuit: num('input_number.house_battery_phase_circuit_limit_w', num('input_number.house_battery_phase_limit_w', 3680)),
    margin: num('input_number.house_battery_phase_margin_w', 200),
    delta: num('input_number.house_battery_phase_switch_soc_delta', 5),
    dwellMs: num('input_number.house_battery_phase_min_dwell', 15) * 60000,
};
// The limiting itself happens in the HBC+ phase planner / guard nodes in 'HBC+ Home Battery Start v1.2';
// this tab stays read-only in every mode.
const modeLabel = cfg.mode;
const count = Math.max(0, Math.min(6, num('input_number.house_battery_count', 0)));
const now = Date.now();
const r = (w) => Math.round(w / ROUND_W) * ROUND_W;

const memo = context.get('phase') || {};      // per phase: {active, dir, since, last_pub, last_key, sharing}
const out = [];

const publish = (topic, payload, key) => {
    const m = memo[topic] || {};
    if (m.last_key === key && now - (m.last_pub || 0) < PUBLISH_EVERY_MS) return;
    m.last_key = key; m.last_pub = now; memo[topic] = m;
    out.push({ payload: { topic, payload: JSON.stringify(payload), retain: true, qos: 1 } });
};

// ---- guard off: say so once, then idle ----
if (cfg.mode === 'Off') {
    for (const ph of PHASES) {
        publish(`hbc/phase/${ph}`, { active: 'off', guard_mode: 'Off', would: 'guard off', reason: 'phase guard is Off' }, 'off');
    }
    publish('hbc/phase/summary', { findings: 0, guard_mode: 'Off' }, 'off');
    context.set('phase', memo);
    node.status({ fill: 'grey', shape: 'ring', text: 'guard Off' });
    return out.length ? [out] : null;
}

// ---- batteries ----
const batteries = [];
for (let i = 1; i <= count; i++) {
    const p = `marstek_m${i}_`;
    batteries.push({
        id: `M${i}`, n: i,
        phase: str(`input_select.${p}phase`, ''),
        soc: num(`sensor.${p}battery_state_of_charge`, NaN),
        power: num(`sensor.${p}battery_power`, NaN),
        rs485: str(`select.${p}rs485_control_mode`, ''),
        socMin: num(`input_number.${p}discharging_cutoff_capacity`, 11),
        socMax: num(`input_number.${p}charging_cutoff_capacity`, 100),
        maxCh: num(`number.${p}max_charge_power`, 0),
        maxDis: num(`number.${p}max_discharge_power`, 0),
    });
}

let findings = 0;
let effMaxCh = 0, effMaxDis = 0, installedCh = 0;
const statusParts = [];

// own-circuit batteries count fully towards the planner maximum
for (const b of batteries) {
    installedCh += b.maxCh || 0;
    if (b.phase === 'Own circuit') { effMaxCh += b.maxCh || 0; effMaxDis += b.maxDis || 0; }
}

for (let pi = 0; pi < PHASES.length; pi++) {
    const ph = PHASES[pi];
    const topic = `hbc/phase/${ph}`;
    const m = memo[topic] || (memo[topic] = {});
    const onPhase = batteries.filter(b => b.phase === ph);
    const p1 = num(`sensor.p1_meter_power_phase_${pi + 1}`, NaN);

    if (onPhase.length === 0) {
        publish(topic, { active: 'none', standby: '', mode: 'idle', guard_mode: modeLabel, would: 'ok', reason: `no battery on ${ph}` }, 'empty');
        statusParts.push(`${ph} -`);
        continue;
    }

    // planner maximum: one battery per phase (or shared) capped by the battery circuit and the grid fuse
    const gridLim = cfg.limit - cfg.margin;
    const circLim = cfg.circuit - cfg.margin;
    const lim = Math.min(gridLim, circLim);
    const maxChOne = Math.max(...onPhase.map(b => b.maxCh || 0));
    const maxDisOne = Math.max(...onPhase.map(b => b.maxDis || 0));
    const sumCh = onPhase.reduce((s, b) => s + (b.maxCh || 0), 0);
    const sumDis = onPhase.reduce((s, b) => s + (b.maxDis || 0), 0);
    effMaxCh += Math.min(lim, cfg.sharing ? sumCh : maxChOne);
    effMaxDis += Math.min(lim, cfg.sharing ? sumDis : maxDisOne);

    // what the batteries do now
    const known = onPhase.every(b => Number.isFinite(b.power));
    const battSum = onPhase.reduce((s, b) => s + (Number.isFinite(b.power) ? b.power : 0), 0);
    const running = onPhase.filter(b => Number.isFinite(b.power) && Math.abs(b.power) > RUNNING_W);
    const dir = battSum > DEADBAND_W ? 'charge' : battSum < -DEADBAND_W ? 'discharge' : 'idle';

    // room = min(grid fuse room, battery circuit room); house net = P1 phase minus the batteries on that phase
    let chRoom = null, disRoom = null;
    if (Number.isFinite(p1) && known) {
        const house = p1 - battSum;
        chRoom = Math.max(0, Math.min(gridLim - house, circLim));
        disRoom = Math.max(0, Math.min(gridLim + house, circLim));
    }
    const room = dir === 'charge' ? chRoom : dir === 'discharge' ? disRoom : null;

    // candidates for this direction
    const isCand = (b, d) => b.rs485 === 'enable' && Number.isFinite(b.soc) && Number.isFinite(b.power)
        && (d === 'charge' ? b.soc < b.socMax : d === 'discharge' ? b.soc > b.socMin : true);
    const cands = dir === 'idle' ? [] : onPhase.filter(b => isCand(b, dir));
    const pref = (a, b) => dir === 'charge' ? a.soc - b.soc : b.soc - a.soc;   // best first

    let active = [];
    let reason = '';
    if (dir === 'idle') {
        reason = 'no battery is working on this phase';
    } else if (cands.length === 0) {
        reason = `no battery can ${dir} (SoC limit, RS485 or no data)`;
    } else if (cfg.sharing) {
        active = cands.slice().sort(pref);
        reason = `shared headroom, ${dir === 'charge' ? 'emptiest' : 'fullest'} first`;
    } else {
        const prev = onPhase.find(b => b.id === m.active);
        const prevOk = prev && cands.includes(prev) && m.dir === dir;
        let pick;
        if (cfg.selection === 'Fixed order') {
            pick = cands.slice().sort((a, b) => a.n - b.n)[0];
            reason = 'fixed order';
        } else if (cfg.selection === 'Rotate daily') {
            const day = Math.floor((now - new Date(new Date(now).getFullYear(), 0, 0)) / 86400000);
            const ordered = onPhase.slice().sort((a, b) => a.n - b.n);
            const primary = ordered[day % ordered.length];
            pick = cands.includes(primary) ? primary : cands[0];
            reason = pick === primary ? 'primary of the day' : `primary ${primary.id} unavailable`;
        } else {
            const best = cands.slice().sort(pref)[0];
            if (prevOk) {
                const gap = Math.abs(best.soc - prev.soc);
                const dwellLeft = cfg.dwellMs - (now - (m.since || 0));
                if (best !== prev && gap >= cfg.delta && dwellLeft <= 0) {
                    pick = best; reason = `SoC gap ${Math.round(gap)} % ≥ ${cfg.delta} %`;
                } else {
                    pick = prev;
                    reason = best === prev ? `${dir === 'charge' ? 'lowest' : 'highest'} SoC`
                        : (gap < cfg.delta ? `kept: SoC gap ${Math.round(gap)} % < ${cfg.delta} %` : `kept: dwell ${Math.ceil(dwellLeft / 60000)} min left`);
                }
            } else {
                pick = best;
                reason = prev && !cands.includes(prev) ? `${prev.id} cannot ${dir}` : `${dir === 'charge' ? 'lowest' : 'highest'} SoC`;
            }
        }
        active = [pick];
    }

    const activeKey = active.map(b => b.id).join('+') || 'none';
    if (activeKey !== m.activeKey || dir !== m.dir) { m.since = now; }
    m.activeKey = activeKey; m.dir = dir; m.active = active.length === 1 ? active[0].id : m.active;

    // what HBC+ would set
    const demand = Math.abs(battSum);
    let setpoint = 0;
    const alloc = {};
    if (active.length && room !== null) {
        let left = Math.min(demand, room);
        active.forEach((b, idx) => {
            const max = dir === 'charge' ? b.maxCh : b.maxDis;
            let give = Math.min(left, max);
            if (idx > 0) {   // shared: partner hysteresis
                const wasOn = (m.sharedOn || []).includes(b.id);
                if (give < (wasOn ? SHARE_STOP_W : SHARE_START_W)) give = 0;
            }
            alloc[b.id] = Math.round(give);
            left -= give;
            setpoint += give;
        });
        m.sharedOn = Object.keys(alloc).filter(id => alloc[id] > 0);
    }

    // differences with what HBC does now
    const would = [];
    if (dir !== 'idle' && room !== null && demand > room + DEADBAND_W) {
        would.push(`limit ${ph} to ${r(room)} W (now ${Math.round(demand)} W)`);
    }
    if (!cfg.sharing && running.length > 1) {
        const idle = running.filter(b => !active.includes(b)).map(b => b.id);
        if (idle.length) would.push(`idle ${idle.join(', ')} (only ${activeKey} may run)`);
    } else if (!cfg.sharing && running.length === 1 && active.length === 1 && running[0] !== active[0]) {
        would.push(`move ${ph} from ${running[0].id} to ${active[0].id}`);
    }
    if (cfg.sharing) {
        for (const b of running) {   // a battery HBC+ would not use at all (cannot serve this direction)
            if (!active.includes(b)) would.push(`idle ${b.id} (${dir === 'charge' ? 'full' : 'empty'} or not controllable)`);
        }
    }
    if (!known) would.push('no data for a battery on this phase');
    if (!Number.isFinite(p1)) would.push(`no P1 data for ${ph}`);
    const wouldTxt = would.length ? would.join('; ') : 'ok';
    if (would.length && known && Number.isFinite(p1)) findings += 1;

    const standby = dir === 'idle' ? '' : onPhase.filter(b => !active.includes(b)).map(b => b.id).join(', ');
    const payload = {
        active: activeKey, standby, mode: dir, guard_mode: modeLabel,
        sharing: cfg.sharing ? 'Shared headroom' : 'One battery per phase',
        room: room === null ? null : r(room),
        charge_room: chRoom === null ? null : r(chRoom),
        discharge_room: disRoom === null ? null : r(disRoom),
        setpoint: r(setpoint), hbc_power: Math.round(battSum),
        allocation: alloc, would: wouldTxt, reason,
        since: new Date(m.since || now).toISOString(),
        handover: !cfg.sharing && running.length === 1 && active.length === 1 && running[0] !== active[0],
    };
    // republish on a real change; numbers only every PUBLISH_EVERY_MS
    publish(topic, payload, [activeKey, standby, dir, wouldTxt, reason, cfg.mode, cfg.sharing].join('|'));
    statusParts.push(`${ph} ${activeKey}${would.length ? '*' : ''}`);
}

publish('hbc/phase/summary', {
    findings, guard_mode: modeLabel, sharing: cfg.sharing ? 'Shared headroom' : 'One battery per phase',
    effective_max_charge: Math.round(effMaxCh), effective_max_discharge: Math.round(effMaxDis),
    installed_max_charge: Math.round(installedCh), updated: new Date(now).toISOString(),
}, [findings, cfg.mode, cfg.sharing, Math.round(effMaxCh), Math.round(effMaxDis)].join('|'));

context.set('phase', memo);
node.status({ fill: findings ? 'yellow' : 'green', shape: 'dot', text: `${modeLabel}: ${statusParts.join(' · ')}${findings ? ` · ${findings} would act` : ''}` });
return out.length ? [out] : null;

// HBC+ (2026-11-15): a Catch node keeps the errors it catches out of the Node-RED log.
// Hand them to the HBC+ logger: Node-RED log (max once a minute per message) and hbc/health.
const handle = global.get('unhandledException');
if (typeof handle === 'function') handle(this);
else node.error(`${(msg.error && msg.error.message) || 'unknown error'}`);
return msg;

// Strategy arbiter - the ONLY writer of input_select.house_battery_strategy.
// Requesters (via link call) send msg.arbiter = {requester, action: 'hold'|'release', strategy, reason, expires?}.
// expires (ms, HBC+ v1.3): the hold is released by 'Hold timeouts' after that moment (requests from HA).
// State (flow 'arb', mirrored to input_text.hbc_strategy_arbiter so it survives restarts):
//   b = base strategy (the user's own choice), h = {requester: {s: strategy, a: active?, x?: expires ms}}
// Effective strategy = highest-priority ACTIVE hold, else the base.
// A manual change (see 'Detect manual change') becomes the new base and marks every hold
// as overridden: an overridden hold is ignored (and not re-applied by repeated 'hold'
// requests) until its requester releases it.
// Priority per requester, higher wins. Any other requester name (a flow of your own) gets
// DEFAULT_PRIO; on equal priority the hold that came first wins. Add a name here to give it
// another priority.
const PRIO = { guard: 100, calibration: 40 };   // calibration: HBC+ v1.3 battery calibration (F4)
const DEFAULT_PRIO = 50;
const prio = (name) => Object.prototype.hasOwnProperty.call(PRIO, name) ? PRIO[name] : DEFAULT_PRIO;
const BAD = ['', 'unknown', 'unavailable', 'None', null, undefined];
try {
    const r = msg.arbiter || {};
    const who = r.requester;
    const cur = msg.current_strategy;
    const ent = msg.strategy_entity || {};
    const options = (ent.attributes && Array.isArray(ent.attributes.options)) ? ent.attributes.options : [];
    const fail = (why) => {
        msg.arbiter_result = 'rejected: ' + why;
        msg.strategy_action = msg.arbiter_result;
        node.warn(`${who}: ${msg.arbiter_result}`);
        node.status({ fill: 'red', shape: 'ring', text: msg.arbiter_result });
        return [null, msg, null, null];
    };
    if (typeof who !== 'string' || !who.trim()) return fail('requester missing');
    if (!['hold', 'release'].includes(r.action)) return fail(`unknown action '${r.action}'`);
    if (r.action === 'hold' && (BAD.includes(r.strategy) || (options.length && !options.includes(r.strategy))))
        return fail(`invalid strategy '${r.strategy}'`);

    const st = flow.get('arb') || { b: null, h: {} };
    if (!st.h || typeof st.h !== 'object') st.h = {};
    const active = () => Object.entries(st.h).filter(([, v]) => v && v.a);
    // While nobody holds, the base simply follows reality.
    if (active().length === 0 && !BAD.includes(cur)) st.b = cur;
    const before = JSON.stringify(st);

    let note;
    const ex = st.h[who];
    if (r.action === 'hold') {
        if (ex && ex.a && ex.s === r.strategy) {
            note = `already holding ${r.strategy}`;
            if (Number.isFinite(r.expires)) ex.x = r.expires; else delete ex.x;
        }
        else if (ex && !ex.a) note = `hold ${ex.s} was overridden manually - ignored until released`;
        else {
            st.h[who] = { s: r.strategy, a: true };
            if (Number.isFinite(r.expires)) st.h[who].x = Math.round(r.expires);
            note = `hold ${r.strategy}`;
        }
    } else {
        if (!ex) note = 'nothing to release';
        else { delete st.h[who]; note = ex.a ? `released ${ex.s}` : `released ${ex.s} (was overridden)`; }
    }

    const act = active().sort((x, y) => prio(y[0]) - prio(x[0]));
    const target = act.length ? act[0][1].s : st.b;
    const changed = JSON.stringify(st) !== before;
    flow.set('arb', st);

    let write = null, action;
    if (changed && !BAD.includes(target) && target !== cur && (!options.length || options.includes(target))) {
        msg.arbiter_target = target;
        flow.set('arb_last_write', { v: target, ts: Date.now() });
        action = `${cur} -> ${target}`;
        write = msg;
    } else {
        action = `unchanged (${cur})`;
    }
    msg.arbiter_result = `${note}; ${action}`;
    msg.strategy_action = msg.arbiter_result;
    node.status({ fill: write ? 'green' : 'grey', shape: 'dot', text: `${who}: ${msg.arbiter_result}`.slice(0, 80) });
    const persist = changed ? { arbiter_state_json: JSON.stringify(st) } : null;
    const log = (changed || write) ? { arbiter_log: `${who}${r.reason ? ' (' + r.reason + ')' : ''}: ${msg.arbiter_result}` } : null;
    return [write, write ? null : msg, persist, log];
} catch (e) {
    node.error('Arbiter failed: ' + e.message, msg);
    msg.arbiter_result = 'error: ' + e.message;
    msg.strategy_action = msg.arbiter_result;
    return [null, msg, null, null];
}

// Every change of the strategy select. Our own writes are recognised by
// arb_last_write (same value, within 15 s) and ignored. Anything else is a manual
// change (dashboard, app, automation): it becomes the new base, and every active hold
// is marked overridden so the arbiter will not put it back.
const BAD = ['', 'unknown', 'unavailable', 'None'];
const v = msg.payload;
if (BAD.includes(v)) return null;
const lw = flow.get('arb_last_write');
if (lw && lw.v === v && Date.now() - lw.ts < 15000) {
    flow.set('arb_last_write', null);
    node.status({ fill: 'grey', shape: 'dot', text: `own write: ${v}` });
    return null;
}
const st = flow.get('arb') || { b: null, h: {} };
if (!st.h || typeof st.h !== 'object') st.h = {};
const over = [];
for (const [k, h] of Object.entries(st.h)) if (h && h.a) { h.a = false; over.push(`${k} (${h.s})`); }
st.b = v;
flow.set('arb', st);
node.status({ fill: 'blue', shape: 'dot', text: `manual: ${v}` + (over.length ? ` | overrides ${over.join(', ')}` : '') });
return [
    { arbiter_state_json: JSON.stringify(st) },
    over.length ? { arbiter_log: `manual change to ${v}; overrides ${over.join(', ')}` } : null
];

// HBC+ (v1.3/v1.4): read the saved arbiter state from the HA states in global context
// ('Expose to global context'), instead of an api-current-state node. Right after a deploy or an HA
// restart that node often ran before Node-RED's entity cache was filled and raised
// 'Entity could not be found in cache', which showed up as an error in sensor.hbc_health.
// Polls every 5 s for up to 2 minutes; if the entity never appears, it warns once and the arbiter
// starts with an empty state (as before when the saved copy was empty).
const ENTITY = 'input_text.hbc_strategy_arbiter';
const read = () => {
    const ha = global.get('homeassistant');
    if (!ha || typeof ha !== 'object') return undefined;
    const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
    const srv = servers.find(s => s.isConnected !== false) || servers[0];
    if (!srv || Object.keys(srv.states).length === 0) return undefined;
    const e = srv.states[ENTITY];
    return e ? String(e.state) : null;   // null = HA states loaded, entity missing
};
let n = 0;
const poll = () => {
    const v = read();
    if (typeof v === 'string') {
        msg.saved_json = v;
        node.status({ fill: 'green', shape: 'dot', text: 'read' });
        node.send(msg);
        return;
    }
    n += 1;
    if (n >= 24) {
        node.warn(v === null
            ? `${ENTITY} does not exist: is packages/hbc_strategy_arbiter.yaml loaded? The arbiter starts empty.`
            : `no HA states in global context after 2 minutes ('Expose to global context' off?). The arbiter starts empty.`);
        node.status({ fill: 'yellow', shape: 'ring', text: v === null ? 'entity missing' : 'no HA states' });
        msg.saved_json = '';
        node.send(msg);
        return;
    }
    node.status({ fill: 'blue', shape: 'ring', text: `waiting for HA states (${n})` });
    setTimeout(poll, 5000);
};
poll();
return null;

// Restore the arbiter state saved in input_text.hbc_strategy_arbiter.
// Does not clobber state that a request may already have created during start-up.
let st = null;
try { st = JSON.parse(msg.saved_json); } catch (e) { st = null; }
if (!st || typeof st !== 'object' || !st.h || typeof st.h !== 'object') st = { b: null, h: {} };
if (!flow.get('arb')) {
    flow.set('arb', st);
    const holds = Object.entries(st.h).map(([k, v]) => `${k}:${v.s}${v.a ? '' : '(overridden)'}`).join(', ');
    node.status({ fill: 'green', shape: 'dot', text: `restored base=${st.b} ${holds}` });
} else {
    node.status({ fill: 'yellow', shape: 'ring', text: 'state already set, saved copy ignored' });
}
return null;

// HBC+ (2026-11-15): a Catch node keeps the errors it catches out of the Node-RED log.
// Hand them to the HBC+ logger: Node-RED log (max once a minute per message) and hbc/health.
const handle = global.get('unhandledException');
if (typeof handle === 'function') handle(this);
else node.error(`${(msg.error && msg.error.message) || 'unknown error'}`);
return msg;

// HBC+ v1.3: a strategy request from Home Assistant (script.hbc_strategy_hold / _release, which
// fire the HA event hbc_arbiter_request). Checked here, then handed to 'Strategy request' like any
// flow of your own. Output 1 -> the arbiter, output 2 -> straight back to HA (rejected).
// The server-events node puts the event data in msg.payload.event (msg.payload.data in older versions).
const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const d = (p.event && typeof p.event === 'object') ? p.event : ((p.data && typeof p.data === 'object') ? p.data : p);
const RESERVED = ['guard', 'manual'];
const who = String(d.requester || '').trim();
const action = String(d.action || '').trim();
const reject = (why) => {
    node.status({ fill: 'red', shape: 'ring', text: `${who || '?'}: ${why}`.slice(0, 80) });
    node.warn(`HA request ${who || '?'}: ${why}`);
    return [null, { payload: { requester: who, action, ok: false, result: 'rejected: ' + why } }];
};
if (!/^[a-z0-9_]{1,32}$/.test(who)) return reject('requester must be 1-32 characters a-z, 0-9 or _');
if (RESERVED.includes(who)) return reject(`requester '${who}' is reserved`);
if (!['hold', 'release'].includes(action)) return reject(`unknown action '${action}'`);
let tmo = Number(d.timeout_min);
if (!Number.isFinite(tmo) || tmo <= 0) tmo = 120;
tmo = Math.min(1440, Math.max(1, Math.round(tmo)));
msg.arbiter = { requester: who, action, reason: d.reason ? String(d.reason).slice(0, 80) : 'Home Assistant' };
if (action === 'hold') {
    msg.arbiter.strategy = String(d.strategy || '');
    msg.arbiter.expires = Date.now() + tmo * 60000;   // the arbiter keeps it with the hold ('x')
}
msg.target = 'Strategy request';   // link call (dynamic) finds the link-in by name
msg.ha_reply = true;
node.status({ fill: 'blue', shape: 'dot', text: `${who}: ${action} ${msg.arbiter.strategy || ''}`.trim().slice(0, 80) });
delete msg.payload;
return [msg, null];

// HBC+ v1.3: the arbiter's answer to a request from HA -> HA event hbc_arbiter_result.
// Releases sent by 'Hold timeouts' carry no ha_reply: they only go to the logbook.
if (!msg.ha_reply) return null;
const r = String(msg.arbiter_result || 'no answer');
msg.payload = { requester: msg.arbiter.requester, action: msg.arbiter.action, ok: !/^(rejected|error)/.test(r), result: r };
return msg;

// HBC+ v1.3: every minute, release holds whose time-out has passed. The expiry ('x', ms) is stored
// with the hold in the arbiter state, so it survives a restart (input_text.hbc_strategy_arbiter).
// Holds without an expiry (the Oscillation Guard, flows of your own) are never touched here.
const st = flow.get('arb');
if (!st || !st.h || typeof st.h !== 'object') return null;
const now = Date.now();
let n = 0;
for (const [who, h] of Object.entries(st.h)) {
    if (h && Number.isFinite(h.x) && h.x <= now) {
        node.send({ arbiter: { requester: who, action: 'release', reason: 'time-out' }, target: 'Strategy request' });
        n++;
    }
}
node.status(n ? { fill: 'yellow', shape: 'dot', text: `released ${n} hold(s) after time-out` } : {});
return null;
